head.script:
// 담당 범위 : maskFormat 가이드 전 항목 (con_maskFormat 1개, 검증 Column 7개를 한 화면에서 비교)
//  - "Body Column 에서만 동작하며 다른 영역의 Column 에 설정 시 무시됩니다." 는 validation 에서 제외 (column 샘플 관례, 설정 영역 con 옵션 미생성, Body Column 에만 설정)
//  - "따라서 DataList 에 저장할 때 제외할 문자는 maskFormatModelExcludeChar 속성에 설정하여야 합니다." 는 다른 속성 안내 문구라 제외 (maskFormatModelExcludeChar 샘플 담당)



// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[column > P > maskFormat]<br/>Column 의 displayFormat 속성에 설정한 마스크 문자에 Cell 값이 매칭되는 방향을 설정합니다.",
    "validation" : [
        "Column 의 displayFormatter 속성 설정 시 maskFormat 속성은 무시됩니다.",
        "Column 의 displayFormat 속성이 설정되고 dataType='text','number' 인 경우에 동작합니다.",
        "'' 설정 시, 마스크 문자의 매칭 방향을 적용하지 않고 dataType 속성값에 따라 displayFormat 속성의 포맷이 적용됩니다.",
        "미설정 시, 마스크 문자의 매칭 방향을 적용하지 않고 dataType 속성값에 따라 displayFormat 속성의 포맷이 적용됩니다.",
        "default 설정 시, 마스크 문자가 왼쪽부터 Cell 값과 매칭됩니다.",
        "default 설정 시, 마스크 문자의 갯수를 넘는 오른쪽의 숫자(문자)는 표시되지 않습니다.",
        "reverse 설정 시, 마스크 문자가 오른쪽부터 Cell 값과 매칭됩니다.",
        "reverse 설정 시, 마스크 문자의 갯수를 넘는 왼쪽의 숫자(문자)는 표시되지 않습니다.",
        "jQuery Mask Plugin 과 유사한 기능을 제공하며 '#' 마스크 문자를 숫자로 대체합니다.",
        "dataType='text' 인 Column 은 displayFormat 속성에 '#' 마스크 문자를 사용합니다.",
        "maskFormat 속성 설정 시 Column 의 allowChar 속성을 설정하지 않으면 숫자만 '#' 마스크 문자와 매칭되며 영문/한글/특수문자 등은 버려집니다.",
        "dataType='number' 인 Column 은 displayFormat 속성에 '#', '0' 마스크 문자를 사용합니다.",
        "maskFormat 속성 설정 시 숫자만 마스크 문자와 매칭되며 값이 채워지지 않은 '0' 마스크 문자는 0 으로 표시됩니다.",
        "maskFormat 속성 설정 시 Column 의 applyFormat='display' 여도 Column 을 편집하는 중에 displayFormat 속성의 포맷이 적용됩니다.",
        "maskFormat 속성 설정 시 바인딩된 DataList 에는 Cell 에 표시된 값이 그대로 저장됩니다."
    ]
}



scwin.gVar = {
    // 편집 중 키를 뗄 때마다 기록한 입력창 값 (셀 더블클릭 시 초기화)
    "editValue" : []
};

// 검증 Column 정보 (id / 출력 라벨 / Header 표시값)
scwin.colInfo = [
    { "id" : "txt",      "label" : "text ###-####",                  "header" : "text ###-####" },
    { "id" : "txtAllow", "label" : "text ###-#### allowChar=A-Z0-9", "header" : "allowChar A-Z0-9" },
    { "id" : "num",      "label" : "number #,###",                   "header" : "number #,###" },
    { "id" : "numZero",  "label" : "number 0,000",                   "header" : "number 0,000" },
    { "id" : "flt",      "label" : "float #,###.##",                 "header" : "float #,###.##" },
    { "id" : "txtNoFmt", "label" : "text displayFormat 미설정",      "header" : "displayFormat 없음" },
    { "id" : "numFmt",   "label" : "number #,### displayFormatter",  "header" : "displayFormatter" }
];



scwin.onpageload = async function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정 (default)
    con_maskFormat.setValue("default");

    // comp 초기 생성
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// displayFormatter 함수 (maskFormat 무시 확인용, Cell 값 뒤에 단위를 붙인다)
scwin.fn_displayFormatter = function (value) {
    return value + " 원";
}



// comp 생성
//  - 검증 Column 7개 모두 inputType='text', applyFormat='display' 이고 con_maskFormat 값을 같은 값으로 설정한다 (미설정은 속성 자체를 넣지 않는다)
//  - txt / txtAllow / txtNoFmt : dataType='text' (txtAllow 는 allowChar='A-Z0-9', txtNoFmt 는 displayFormat 미설정)
//  - num / numZero / numFmt : dataType='number' (numFmt 는 displayFormatter 함께 설정)
//  - flt : dataType='float' (text / number 외 dataType 대조)
scwin.comp_init = async function () {
    // 기존 target / dataList / label 삭제
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove("dlt_bind");
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }
    scwin.gVar.editValue = [];

    // 테스트 정보 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] 모든 검증 Column 은 inputType=text, applyFormat=display 이고 maskFormat 은 옵션값으로 함께 설정 (Column 별 dataType / displayFormat 은 결과창 출력 라벨 참고)\n[절차] 옵션 선택 -> Target 재생성 -> 생성 시 출력된 Column 별 Cell 값 -> 표시값 확인\n[절차] 결과창 clear -> text / number Column 셀 더블클릭 -> 입력값을 지우고 숫자를 한 자씩 입력 (예: 0298765432) -> 결과창 클릭으로 편집 종료\n[확인] 편집 중 입력창 값과 편집 종료 후 셀 표시값 / DataList 저장값 자동 출력"', '', 'label1');

    // 조건 설정 (자체 값 select -> getValue, 미설정은 속성 자체를 넣지 않고 '' 는 maskFormat="" 를 그대로 넣는다)
    let cMaskFormat = con_maskFormat.getValue();
    let attrMask = '';
    if (cMaskFormat === "__empty") {
        attrMask = ' maskFormat=""';
    } else if (cMaskFormat !== '') {
        attrMask = ' maskFormat="' + cMaskFormat + '"';
    }

    let strNameSpace = $c.gcm.getNameSpace();
    let grp_comp = $c.gcm.getTestGroup();

    // 바인딩 dataList (body column id 와 동일한 컬럼 id 사용)
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="txt" name="txt" dataType="text"></w2:column>';
    strDlt += '<w2:column id="txtAllow" name="txtAllow" dataType="text"></w2:column>';
    strDlt += '<w2:column id="num" name="num" dataType="number"></w2:column>';
    strDlt += '<w2:column id="numZero" name="numZero" dataType="number"></w2:column>';
    strDlt += '<w2:column id="flt" name="flt" dataType="number"></w2:column>';
    strDlt += '<w2:column id="txtNoFmt" name="txtNoFmt" dataType="text"></w2:column>';
    strDlt += '<w2:column id="numFmt" name="numFmt" dataType="number"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
    dlt_bind.setJSON([
        { "txt" : "02123456789", "txtAllow" : "02123456789", "num" : "1234567", "numZero" : "1234567", "flt" : "1234567.89", "txtNoFmt" : "02123456789", "numFmt" : "1234567" },
        { "txt" : "TEL 12-345",  "txtAllow" : "TEL 12-345",  "num" : "1200",    "numZero" : "7",       "flt" : "5.5",        "txtNoFmt" : "TEL 12-345",  "numFmt" : "1200" }
    ], false);

    // 이벤트 바인딩 (편집 종료 시 저장값 출력)
    let eList = $c.gcm.createEList(["onviewchange"]);

    // 검증 Column 공통 속성
    let attrCommon = ' inputType="text" applyFormat="display"' + attrMask;

    // target 생성
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + eList + ' dataList="data:dlt_bind" checkAllType="false" defaultCellHeight="30" id="" style="width:910px;height:120px;">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    for (let i = 0; i < scwin.colInfo.length; i++) {
        strTarget += '<w2:column width="130" style="" inputType="text" id="column' + (i + 1) + '" value="' + scwin.colInfo[i].header + '"></w2:column>';
    }
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="130" style="" id="txt" value=""' + attrCommon + ' dataType="text" displayFormat="###-####"></w2:column>';
    strTarget += '<w2:column width="130" style="" id="txtAllow" value=""' + attrCommon + ' dataType="text" displayFormat="###-####" allowChar="A-Z0-9"></w2:column>';
    strTarget += '<w2:column width="130" style="" id="num" value=""' + attrCommon + ' dataType="number" displayFormat="#,###"></w2:column>';
    strTarget += '<w2:column width="130" style="" id="numZero" value=""' + attrCommon + ' dataType="number" displayFormat="0,000"></w2:column>';
    strTarget += '<w2:column width="130" style="" id="flt" value=""' + attrCommon + ' dataType="float" displayFormat="#,###.##"></w2:column>';
    strTarget += '<w2:column width="130" style="" id="txtNoFmt" value=""' + attrCommon + ' dataType="text"></w2:column>';
    strTarget += '<w2:column width="130" style="" id="numFmt" value=""' + attrCommon + ' dataType="number" displayFormat="#,###" displayFormatter="scwin.fn_displayFormatter"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );

    // 편집 입력창 값 기록 (셀 더블클릭(편집 진입) 시 기록 초기화)
    target1.render.addEventListener("dblclick", function () {
        scwin.gVar.editValue = [];
    }, true);
    target1.render.addEventListener("keyup", scwin.recordEditValue, true);

    // validation 1 ~ 13 판정 출력 : Column 별 Cell 값(DataList) -> 셀 표시값
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.setReturnValue("maskFormat : " + (cMaskFormat === "__empty" ? "''" : (cMaskFormat === '' ? "(미설정)" : cMaskFormat)));
    for (let i = 0; i < scwin.colInfo.length; i++) {
        let arr = [];
        for (let r = 0; r < dlt_bind.getRowCount(); r++) {
            arr.push(dlt_bind.getCellData(r, scwin.colInfo[i].id) + " -> " + scwin.getCellText(r, i));
        }
        bottom.setReturnValue(scwin.colInfo[i].label + " : " + arr.join(" / "));
    }
}



// 셀 표시값 (maskFormat + displayFormat Column 은 getCellDisplayData 가 값을 반환하지 않아 화면 Cell 의 텍스트를 읽는다)
scwin.getCellText = function (rowIndex, colIndex) {
    let td = document.querySelector("td[id*='" + target1.id + "_cell_" + rowIndex + "_" + colIndex + "']");
    return td ? td.textContent : "";
}



// 편집 중 키를 뗄 때마다 입력창 값을 기록 (입력창의 포맷 처리가 끝난 뒤의 값을 읽는다)
scwin.recordEditValue = function (e) {
    let elem = e.target;
    if (!elem || elem.tagName !== "INPUT") {
        return;
    }
    setTimeout(function () {
        let arr = scwin.gVar.editValue;
        if (arr.length === 0 || arr[arr.length - 1] !== elem.value) {
            arr.push(elem.value);
        }
    }, 0);
}



// validation 14, 15 판정 출력 : 편집 중 입력창 값 / 편집 종료 후 셀 표시값 / DataList 저장값
scwin.target1_onviewchange = function (info) {
    let colId = target1.getColumnID(info.colIndex);
    wf_body_bottom.getObj("scwin").setReturnValue("Row " + info.rowIndex + " / " + scwin.colInfo[info.colIndex].label
        + " 편집 중 입력창 값 : " + scwin.gVar.editValue.join(" > ")
        + " -> 셀 표시값 : " + scwin.getCellText(info.rowIndex, info.colIndex)
        + " / DataList 저장값 : " + dlt_bind.getCellData(info.rowIndex, colId));
}
